# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">SINIF ARKADAŞLARIM VE ÖĞRETMENİM (صَدِيقِي / صَدِيقَتِي - طَالِبٌ / طَالِبَةٌ)</text>\n  <rect x="20" y="46" width="320" height="194" rx="8" fill="#eff6ff" stroke="#2563eb" stroke-width="1.5"/>\n  <text x="180" y="70" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Eril Kişi ve Tanıtım Kalıpları (مُذَكَّر)</text>\n  <text x="180" y="98" text-anchor="middle" font-size="12" fill="#1e3a8a">• طَالِبٌ (Erkek öğrenci) · مُعَلِّمٌ (Erkek öğretmen)</text>\n  <text x="180" y="124" text-anchor="middle" font-size="12" fill="#1e3a8a">• صَدِيقِي (Erkek arkadaşım) · زَمِيلِي (Sınıf arkadaşım)</text>\n  <text x="180" y="150" text-anchor="middle" font-size="12" fill="#1e3a8a">• مَنْ هٰذَا؟ (Bu kimdir? - Eril için soru)</text>\n  <text x="180" y="176" text-anchor="middle" font-size="12" fill="#1e3a8a">• هٰذَا صَدِيقِي أَحْمَدُ، هُوَ طَالِبٌ.</text>\n  <text x="180" y="200" text-anchor="middle" font-size="11.5" fill="#1e3a8a">(Bu arkadaşım Ahmet\'tir, o bir öğrencidir.)</text>\n  <text x="180" y="226" text-anchor="middle" font-size="11" font-weight="bold" fill="#1d4ed8">Zamir uyumu: هٰذَا + هُوَ (O - Eril)</text>\n\n  <rect x="360" y="46" width="320" height="194" rx="8" fill="#fdf2f8" stroke="#db2777" stroke-width="1.5"/>\n  <text x="520" y="70" text-anchor="middle" font-size="13" font-weight="bold" fill="#be185d">Dişil Kişi ve Tanıtım Kalıpları (مُؤَنَّث)</text>\n  <text x="520" y="98" text-anchor="middle" font-size="12" fill="#831843">• طَالِبَةٌ (Kız öğrenci) · مُعَلِّمَةٌ (Kadın öğretmen)</text>\n  <text x="520" y="124" text-anchor="middle" font-size="12" fill="#831843">• صَدِيقَتِي (Kız arkadaşım) · زَمِيلَتِي (Sınıf arkadaşım)</text>\n  <text x="520" y="150" text-anchor="middle" font-size="12" fill="#831843">• مَنْ هٰذِهِ؟ (Bu kimdir? - Dişil için soru)</text>\n  <text x="520" y="176" text-anchor="middle" font-size="12" fill="#831843">• هٰذِهِ صَدِيقَتِي زَيْنَبُ، هِيَ طَالِبَةٌ.</text>\n  <text x="520" y="200" text-anchor="middle" font-size="11.5" fill="#831843">(Bu arkadaşım Zeynep\'tir, o bir öğrencidir.)</text>\n  <text x="520" y="226" text-anchor="middle" font-size="11" font-weight="bold" fill="#be185d">Zamir uyumu: هٰذِهِ + هِيَ (O - Dişil)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">ARAPÇADA BİTİŞİK İYELİK ZAMİRLERİ (ـِي ، ـكَ ، ـكِ)</text>\n  <rect x="20" y="48" width="210" height="190" rx="8" fill="#f0fdf4" stroke="#16a34a" stroke-width="1.5"/>\n  <text x="125" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Benim (ـِي - Mütekellim Yâ\'sı)</text>\n  <text x="125" y="102" text-anchor="middle" font-size="12" fill="#14532d">• كِتَابٌ → كِتَابِي (Kitabım)</text>\n  <text x="125" y="128" text-anchor="middle" font-size="12" fill="#14532d">• قَلَمٌ → قَلَمِي (Kalemim)</text>\n  <text x="125" y="154" text-anchor="middle" font-size="12" fill="#14532d">• حَقِيبَةٌ → حَقِيبَتِي (Çantam)</text>\n  <text x="125" y="180" text-anchor="middle" font-size="12" fill="#14532d">• مَدْرَسَةٌ → مَدْرَسَتِي (Okulum)</text>\n  <text x="125" y="216" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">Erkek ve kız konuşmacı için ortaktır.</text>\n\n  <rect x="245" y="48" width="210" height="190" rx="8" fill="#fef3c7" stroke="#d97706" stroke-width="1.5"/>\n  <text x="350" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#b45309">Senin - Eril (ـكَ - Muhatap)</text>\n  <text x="350" y="102" text-anchor="middle" font-size="12" fill="#78350f">• كِتَابُكَ (Senin kitabın - Erkek)</text>\n  <text x="350" y="128" text-anchor="middle" font-size="12" fill="#78350f">• دَفْتَرُكَ (Senin defterin)</text>\n  <text x="350" y="154" text-anchor="middle" font-size="12" fill="#78350f">• مِمْحَاتُكَ (Senin silgin)</text>\n  <text x="350" y="180" text-anchor="middle" font-size="12" fill="#78350f">• مَا اسْمُكَ؟ (Adın nedir?)</text>\n  <text x="350" y="216" text-anchor="middle" font-size="11" font-weight="bold" fill="#b45309">Üstün harekeli كَ harfi eklenir.</text>\n\n  <rect x="470" y="48" width="210" height="190" rx="8" fill="#ecfeff" stroke="#0891b2" stroke-width="1.5"/>\n  <text x="575" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#0e7490">Senin - Dişil (ـكِ - Muhataba)</text>\n  <text x="575" y="102" text-anchor="middle" font-size="12" fill="#155e75">• كِتَابُكِ (Senin kitabın - Kız)</text>\n  <text x="575" y="128" text-anchor="middle" font-size="12" fill="#155e75">• دَفْتَرُكِ (Senin defterin)</text>\n  <text x="575" y="154" text-anchor="middle" font-size="12" fill="#155e75">• حَقِيبَتُكِ (Senin çantan)</text>\n  <text x="575" y="180" text-anchor="middle" font-size="12" fill="#155e75">• مَا اسْمُكِ؟ (Adın nedir?)</text>\n  <text x="575" y="216" text-anchor="middle" font-size="11" font-weight="bold" fill="#0e7490">Esre harekeli كِ harfi eklenir.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">SINIF İÇİ İLETİŞİM, ÖDÜNÇ İSTEME VE TEŞEKKÜR DİYALOGLARI</text>\n  <rect x="25" y="48" width="650" height="190" rx="8" fill="#f5f3ff" stroke="#7c3aed" stroke-width="1.5"/>\n  <text x="350" y="74" text-anchor="middle" font-size="13" font-weight="bold" fill="#5b21b6">Örnek Sınıf İçi Diyalog (حِوَارٌ فِي الصَّفِّ)</text>\n  <text x="60" y="104" font-size="12" font-weight="bold" fill="#4c1d95">• الطَّالِبُ:</text>\n  <text x="140" y="104" font-size="12" fill="#1e293b">مِنْ فَضْلِكَ يَا صَدِيقِي، أَعْطِنِي القَلَمَ. (Lütfen arkadaşım, bana kalemi ver.)</text>\n  <text x="60" y="132" font-size="12" font-weight="bold" fill="#4c1d95">• الصَّدِيقُ:</text>\n  <text x="140" y="132" font-size="12" fill="#1e293b">تَفَضَّلْ، خُذِ القَلَمَ. (Buyur, kalemi al.)</text>\n  <text x="60" y="160" font-size="12" font-weight="bold" fill="#4c1d95">• الطَّالِبُ:</text>\n  <text x="140" y="160" font-size="12" fill="#1e293b">شُكْرًا جَزِيلًا يَا صَدِيقِي. (Çok teşekkür ederim arkadaşım.)</text>\n  <text x="60" y="188" font-size="12" font-weight="bold" fill="#4c1d95">• الصَّدِيقُ:</text>\n  <text x="140" y="188" font-size="12" fill="#1e293b">عَفْوًا! اَلْعِلْمُ نَافِعٌ وَالتَّعَاوُنُ جَمِيلٌ. (Rica ederim! İlim faydalıdır ve yardımlaşmak güzeldir.)</text>\n  <text x="350" y="220" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#6d28d9">Nezaket ifadeleri: مِنْ فَضْلِكَ / مِنْ فَضْلِكِ (Lütfen) · تَفَضَّلْ / تَفَضَّلِي (Buyur) · شُكْرًا (Teşekkürler) · عَفْوًا (Rica ederim)</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
